function intToRoman(num: number): string {
  // Все «атомы» римской записи по убыванию, включая вычитательные формы
  const values = [1000, 900, 500, 400, 100, 90, 50, 40, 10, 9, 5, 4, 1];
  const symbols = ['M', 'CM', 'D', 'CD', 'C', 'XC', 'L', 'XL', 'X', 'IX', 'V', 'IV', 'I'];

  let result = '';
  for (let i = 0; i < values.length && num > 0; i++) {
    // Жадно берём самый большой атом, пока он помещается в остаток
    while (num >= values[i]) {
      result += symbols[i];
      num -= values[i];
    }
  }

  return result;
}

// Время: O(1) — длина результата ограничена (не больше 15 символов при num <= 3999)
